// ------------------------------------------------------------ boundaries

/// Mur faces in a medium: the TEM line of 400 cells filled with ε_r = 4,
/// Mur on both ends without `MUR_PhaseVelocity`. openEMS tunes each edge
/// to the local medium (ems now does too, `MurBoundary::with_faces_in`):
/// 0.9–1.2e-6 (with the vacuum speed the reflections were 34–49 %).
#[test]
fn mur_in_dielectric() {
    check("adv_mur_dielectric", 2e-5);
}

/// `PML_8` on a vacuum line: openEMS's PML reflects about 1.3e-3 of the
/// signal at the probes (−58 dB; ems's own CPML 5e-5, −86 dB); the
/// reference is ems on a line long enough for no reflection to return
/// (`reference.xml`). For files ems runs openEMS's layer (design §5.6,
/// §5.16.2): the same reflection, and the probes agree to 7e-7.
#[test]
fn pml_reflection_like_openems() {
    let name = "adv_pml_vacuum";
    let res = run(name, &CompileOptions::default());
    let mut sim = Simulation::from_xml(fixture_dir(name).join("reference.xml")).unwrap();
    let r = sim.run().unwrap();
    for f in ["ut_a", "ut_c"] {
        let (_, oe, ems) = at_oe_times(name, f, &res);
        let (_, _, inc) = at_oe_times(name, f, &r);
        let norm = |x: &[f64]| x.iter().map(|v| v * v).sum::<f64>().sqrt();
        let refl = |x: &[f64]| {
            let d: Vec<f64> = x.iter().zip(&inc).map(|(a, b)| a - b).collect();
            norm(&d) / norm(&inc)
        };
        let (r_oe, r_ems) = (refl(&oe), refl(&ems));
        eprintln!("{f}: reflected part openEMS {r_oe:.2e}, ems {r_ems:.2e}");
        assert!(r_oe > 8e-4 && r_oe < 2e-3, "{f}: openEMS {r_oe}");
        assert!((r_ems / r_oe - 1.0).abs() < 1e-3, "{f}: ems {r_ems}");
    }
    check(name, 2e-6);
}

/// openEMS ignores `PML_Grading` on `<BoundaryCond>`: the same vacuum
/// line with `PML_Grading="1e9*D"` gives bit-identical probe files (its
/// operator dump is unchanged too, for any expression, even one with
/// unknown variables). ems ignores it as well, with a warning, and gives
/// the same signals as without it.
#[test]
fn pml_grading_is_ignored() {
    let (a, b) = ("adv_pml_grading", "adv_pml_vacuum");
    for f in ["ut_a", "ut_c"] {
        let rows = |c: &str| -> Vec<String> {
            std::fs::read_to_string(fixture_dir(c).join(f))
                .unwrap()
                .lines()
                .filter(|l| !l.starts_with('%'))
                .map(str::to_string)
                .collect()
        };
        assert_eq!(rows(a), rows(b), "{f}");
    }
    let path = fixture_dir(a).join("model.xml");
    let sim = Simulation::from_xml(&path).unwrap();
    assert!(
        sim.warnings().iter().any(|w| w.contains("PML_Grading")),
        "{:?}",
        sim.warnings()
    );
    let (ra, rb) = (
        run(a, &CompileOptions::default()),
        run(b, &CompileOptions::default()),
    );
    for f in ["ut_a", "ut_c"] {
        assert_eq!(ra.probe(f).unwrap().values(), rb.probe(f).unwrap().values());
    }
}

