/// A radial 20 Ω lumped resistor over the whole ring of a closed-azimuth
/// coax (16 α cells, 12 radial edges): openEMS spreads it like a
/// homogeneous conductivity (`R_e ∝ 1/ρ`, which ems now does for files)
/// but normalises it over 17 α columns, counting the α = 2π copy of each
/// edge, so its ring is 21.25 Ω. ems keeps the nominal 20 Ω (2–5e-2
/// difference); with `R` = 20·17/16 the codes agree to ~1e-6.
#[test]
fn cylindrical_lumped_ring() {
    let name = "adv_cyl_lumped_ring";
    let res = run(name, &CompileOptions::default());
    for (f, e) in compare(name, &res) {
        assert!(e > 5e-3 && e < 0.1, "{name}/{f}: nominal R, {e:.3e}");
    }
    let xml = std::fs::read_to_string(fixture_dir(name).join("model.xml")).unwrap();
    let scaled = xml.replace(r#"R="20""#, r#"R="21.25""#);
    assert_ne!(scaled, xml);
    let mut sim = Simulation::from_xml_str(&scaled).unwrap();
    let res = sim.run().unwrap();
    for (f, e) in compare(name, &res) {
        assert!(e < 2e-5, "{name}/{f}: R·17/16, {e:.3e}");
    }
}

// ------------------------------------------------------------ waveguide probes

/// TE10 in a 20 × 10 mm guide (PEC, 1 mm cells, `sin(πx/20)`-weighted Ey
/// source), mode probes at z = 30 mm with mode functions `sin(πx/20)`,
/// `1` and `x` (drawing units), over the full guide and over the box
/// 4…16 × 2…8 mm: openEMS's normalised, node/cell sampled mode matching
/// (`compile/mode.rs`). Measured 2.8–3.5e-7.
#[test]
fn waveguide_probes_te10() {
    let name = "adv_wg_te10";
    let res = run(name, &CompileOptions::default());
    for (f, e) in compare(name, &res) {
        assert!(e < 2e-5, "{name}/{f}: relative L2 {e:.3e} > 2e-5");
    }
    // Purity: 1 for the matched mode (voltage; the current's half-cell
    // offset gives 0.9945), 0.8497 / 0.6536 against `1` / `x`.
    check_mode_files(name, &res, 1e-4);
}

/// The mode-matching files of every kept probe of `name`, written by
/// ems (`ems::io::openems`), against openEMS's: kind, columns, position
/// lines, and the `mode_purity` column at the samples where the probe's
/// value is above 1 % of its peak (the purity of a vanishing field is
/// the ratio of round-off terms), to `tol` absolute. Measured: ≤ 1e-5
/// (2e-7 and less for most probes).
fn check_mode_files(name: &str, res: &Results, tol: f64) {
    let dir = std::env::temp_dir().join(format!("ems-adv-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    ems::io::openems::write_probes(res, &dir).unwrap();
    for f in meta(name, "keep")[0].split_whitespace() {
        let oe = oe_probe(name, f);
        let ours = read_probe_file(dir.join(f)).unwrap();
        assert!(oe.kind.is_mode_matching(), "{name}/{f}: {:?}", oe.kind);
        assert_eq!(ours.kind, oe.kind, "{name}/{f}");
        assert_eq!(ours.location, oe.location, "{name}/{f}: position lines");
        let (vo, po) = (oe.column(0), oe.mode_purity().unwrap());
        let (ve, pe) = (ours.column(0), ours.mode_purity().unwrap());
        let peak = vo.iter().fold(0.0f64, |m, v| m.max(v.abs()));
        let mut worst = 0.0f64;
        for k in 0..vo.len().min(ve.len()) {
            if vo[k].abs() > 1e-2 * peak {
                worst = worst.max((pe[k] - po[k]).abs());
            }
        }
        eprintln!(
            "{name}/{f}: mode purity {:.6} (max |Δ| {worst:.1e})",
            po[po.len() / 2]
        );
        assert!(worst < tol, "{name}/{f}: mode purity off by {worst:e}");
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// A TE11-like field on a graded mesh (0.5…1.5 mm cells around the node
/// x = 5, y = 5 mm) with full mode functions and with indicators that
/// select the single node (voltage: linear interpolation of E, dual area)
/// and the single cell (current: `f` at the cell centre, cell area).
/// Measured 3.7–9.7e-6, and 4.7e-4 for the node indicator, which sits in
/// a field null (cancellation of its two edge contributions).
#[test]
fn waveguide_probes_graded() {
    let name = "adv_wg_graded";
    let res = run(name, &CompileOptions::default());
    for (f, e) in compare(name, &res) {
        let tol = if f == "wv_node" { 3e-3 } else { 1e-4 };
        assert!(e < tol, "{name}/{f}: relative L2 {e:.3e} > {tol:e}");
    }
    check_mode_files(name, &res, 1e-4);
}

// ------------------------------------------------------------ sheets

/// ems's signal of `name`'s probe `f` at the openEMS sample times of the
/// fixture (they coincide: same `dt`).
fn at_oe_times(name: &str, f: &str, res: &Results) -> (Vec<f64>, Vec<f64>, Vec<f64>) {
    let oe = oe_probe(name, f);
    let p = res.probe(f).unwrap();
    let (t, v) = (p.times(), p.scalar().unwrap());
    let oe_t = oe.abscissa();
    let ems = oe_t
        .iter()
        .map(|&x| {
            let k = t.partition_point(|&y| y < x - 1e-3 * res.dt());
            if k < t.len() { v[k] } else { 0.0 }
        })
        .collect();
    (oe_t, oe.column(0), ems)
}

/// openEMS's `ConductingSheet` is a different (fitted) model, which ems
/// emulates for files (`compile/openems_sheet.rs`, design §5.16.2): a
/// 35 µm copper sheet across a TEM line of two cells reflects with
/// `1 − |Γ|` equal to 0.48–0.52 of the exact slab's `≈ 2R_s/η0` (ems's
/// native slab: 1, design §5.9), because openEMS leaves the sheet's
/// first cell row next to the lower mesh boundary out, so only half the
/// sheet width carries current. The probes are identical to the printed
/// digits (openEMS's sheet arithmetic and its H edges at the PMC face,
/// design §5.16.13; 8e-12 and 1.3e-6 before). The incident wave is the
/// same in both codes (sheet removed: ems's reference run).
#[test]
fn conducting_sheet_copper_loss_is_half_in_openems() {
    let name = "adv_sheet_copper";
    let res = run(name, &CompileOptions::default());
    for (f, e) in compare(name, &res) {
        assert!(e < 1e-9, "{name}/{f}: relative L2 {e:.3e}");
    }
    let xml = std::fs::read_to_string(fixture_dir(name).join("model.xml")).unwrap();
    let (a, b) = (
        xml.find("<ConductingSheet").unwrap(),
        xml.find("</ConductingSheet>").unwrap() + "</ConductingSheet>".len(),
    );
    let reference = format!("{}{}", &xml[..a], &xml[b..]);
    let mut sim = Simulation::from_xml_str(&reference).unwrap();
    let r = sim.run().unwrap();
    let (t, oe, ems) = at_oe_times(name, "ut_a", &res);
    let (_, _, inc) = at_oe_times(name, "ut_a", &r);
    let dt = t[1] - t[0];
    let freqs: Vec<f64> = (2..=9).map(|k| k as f64 * 1e9).collect();
    let refl = |x: &[f64]| {
        let d: Vec<f64> = x.iter().zip(&inc).map(|(a, b)| a - b).collect();
        let (g, i) = (
            ems::post::dft(t[0], dt, &d, &freqs),
            ems::post::dft(t[0], dt, &inc, &freqs),
        );
        g.iter()
            .zip(&i)
            .map(|(g, i)| 1.0 - (*g / *i).norm())
            .collect::<Vec<_>>()
    };
    let (l_oe, l_ems) = (refl(&oe), refl(&ems));
    let (mu0, eta0) = (4e-7 * std::f64::consts::PI, 376.730_313_668);
    for (k, f) in freqs.iter().enumerate() {
        let rs = (std::f64::consts::PI * f * mu0 / 5.8e7).sqrt();
        let exact = 2.0 * rs / eta0;
        let (q_oe, q_ems) = (l_oe[k] / exact, l_ems[k] / exact);
        eprintln!(
            "{:.0} GHz: 1-|Γ| openEMS/slab {q_oe:.3}, ems/slab {q_ems:.3}",
            f / 1e9
        );
        // 1 − |Γ| ≈ 1e-4: a 3e-7 signal difference moves it by 1 %.
        assert!((q_ems - q_oe).abs() < 0.02, "{f}: ems {q_ems}");
        assert!((q_oe - 0.5).abs() < 0.05, "{f}: openEMS {q_oe}");
    }
}

// ------------------------------------------------------------ plane waves

// openEMS's incident field lags ems's reference (`a(t)` at the entry
// corner) by one time step plus the travel time across the box's first
// cell; with that (`compile::planewave::openems_lag`) the remaining
// difference is openEMS's own injection error (its scattered-field
// leakage is −37 dB at 1 mm, −53 dB at 0.5 mm, against below −120 dB in
// ems), which grows with the distance into the box like a dispersion
// error: 2e-2 after 20 cells of 1 mm, 4e-3 at 0.5 mm, 5e-4…1.5e-3 a few
// cells into the 3-D boxes.

